  const found = WORKSPACE_MCP_FILES.map((f) => path.join(root, f)).filter((f) => fs.existsSync(f));
  for (const dir of WORKSPACE_PLUGIN_DIRS) {
    try {
      for (const name of fs.readdirSync(path.join(root, dir))) {
